// AirPods Approvals for Hermes Desktop.
//
// GENERATED by scripts/build.py from src/desktop.js + src/engine.mjs + src/ui.css — edit those.
// Plain ESM loaded uncompiled by the Desktop plugin loader: imports only the SDK and React.
import { Button, Input, ListRow, STATUSBAR_AREAS, PALETTE_AREA, ToggleRow, Codicon, SegmentedControl, atom, host, pluginSettingsHref, useValue } from '@hermes/plugin-sdk'
import { useState } from 'react'
import { jsx, jsxs } from 'react/jsx-runtime'

// The logic behind AirPods Approvals: what gets asked, what is said, and when an answer may reach
// Hermes. No SDK or browser globals here, so every rule is tested by tests/engine.test.mjs.
//
// The rule that matters most: Hermes only hears "once" after a completed gesture from the helper
// and a fresh check that this exact request is still waiting. Every other path sends nothing, so
// the prompt stays on screen and Hermes' own timeout denies it.

const HELPER_URL = 'ws://127.0.0.1:47291'
// Desktop opens a bare local path with macOS, which starts the helper. Custom URL schemes are refused.
const HELPER_APP = '~/Applications/Hermes AirPods.app'

const DEFAULT_SETTINGS = {
  enabled: true,
  confirmApprovals: false,
  listenSeconds: 8,
  questions: true,
}

const SEEN_LIMIT = 300

function clip(value, limit) {
  const text = String(value == null ? '' : value).replace(/\s+/g, ' ').trim()
  return text.length > limit ? `${text.slice(0, limit - 1).trimEnd()}…` : text
}

// The closing instruction is always ours and always last, so text inside a command can't change
// what a nod means.
function approvalSpeech(request) {
  const reason = clip(request.description, 160).replace(/[.\s]+$/, '')
  const command = clip(request.command, 140)
  const parts = ['Hermes needs your approval.']
  if (reason) parts.push(`${reason}.`)
  if (command) parts.push(`The command is: ${command}.`)
  parts.push('Nod to approve, or shake to deny.')
  return parts.join(' ')
}

function pickerSpeech(question, choices) {
  const [first, second] = choices
  return `${clip(question, 200)} Nod for ${clip(first, 60)}. Shake for ${clip(second, 60)}.`
}

function optionSpeech(question, choice, index, total) {
  const lead = index === 0 ? `${clip(question, 200)} ` : ''
  return `${lead}Option ${index + 1} of ${total}: ${clip(choice, 80)}. Nod to choose it, or shake for the next.`
}

// One plain question with choices can be answered by head. Anything else is read aloud and left
// on screen.
function questionPlan(params) {
  const questions = Array.isArray(params.questions) ? params.questions : []
  if (questions.length !== 1) return { mode: 'read', text: 'Hermes has some questions for you on screen.' }
  const q = questions[0]
  const choices = (Array.isArray(q.choices) ? q.choices : []).map(String).filter(Boolean)
  if (q.multi_select || choices.length < 2) {
    return { mode: 'read', text: `Hermes asks: ${clip(q.question, 240)} Please answer on screen.` }
  }
  return { mode: choices.length === 2 ? 'pair' : 'list', qid: q.qid, question: q.question, choices }
}

function hex(bytes) {
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')
}

// The authenticated link to the Mac helper. Nothing from the helper counts until it has proved it
// holds the pairing token, so a process squatting on the port can't forge an answer.
class HelperLink {
  constructor({ createSocket, token, sign, nonce, onChange, setTimer }) {
    Object.assign(this, { createSocket, token, sign, nonce, onChange, setTimer })
    this.socket = null
    this.trusted = false
    this.status = {}
    this.waiting = new Map()
    this.progress = () => {}
    this.closed = false
    // Set only when the user presses Connect. The token is never offered to the helper otherwise,
    // so something squatting on the port can't collect it in the background.
    this.pairUntil = 0
    this.refused = false
  }

  pairSoon(now = Date.now()) {
    this.pairUntil = now + 20000
    this.refused = false
  }

  get connected() {
    return this.trusted
  }

  connect() {
    if (this.closed || this.socket) return
    const secret = this.token()
    if (!secret) return
    let socket
    try {
      socket = this.createSocket(HELPER_URL)
    } catch {
      this.retry()
      return
    }
    this.socket = socket
    const clientNonce = this.nonce()
    socket.onmessage = event => this.receive(socket, secret, clientNonce, event.data)
    socket.onclose = () => this.dropped(socket)
    socket.onerror = () => {}
  }

  retry() {
    if (!this.closed) this.setTimer(() => this.connect(), Date.now() < this.pairUntil ? 700 : 3000)
  }

  dropped(socket) {
    if (socket !== this.socket) return
    // The helper hung up after our hello during a Connect: it is paired with another token.
    if (!this.trusted && this.offered) {
      this.refused = true
      this.pairUntil = 0
    }
    this.offered = false
    this.socket = null
    this.trusted = false
    this.onChange()
    for (const resolve of this.waiting.values()) resolve({ reason: 'lost' })
    this.waiting.clear()
    this.retry()
  }

  close() {
    this.closed = true
    if (this.socket) this.socket.close()
  }

  async receive(socket, secret, clientNonce, data) {
    let message
    try {
      message = JSON.parse(data)
    } catch {
      return
    }
    if (socket !== this.socket) return

    if (!this.trusted) {
      if (message.type === 'challenge') {
        const pairing = Date.now() < this.pairUntil
        if (pairing && (message.paired === false || message.pairing === true)) {
          socket.send(JSON.stringify({ type: 'pair', token: secret }))
        } else if (message.paired === false) {
          socket.close()
          return
        }
        const proof = await this.sign(secret, `plugin:${message.nonce}`)
        socket.send(JSON.stringify({ type: 'hello', nonce: clientNonce, proof }))
        this.offered = pairing
      } else if (message.type === 'ready') {
        if (message.proof !== (await this.sign(secret, `helper:${clientNonce}`))) {
          socket.close()
          return
        }
        this.trusted = true
        this.pairUntil = 0
        this.refused = false
        this.status = message
        this.onChange()
      }
      return
    }

    if (message.type === 'status') {
      this.status = message
      this.onChange()
    } else if (message.type === 'progress') {
      this.progress(message)
    } else if (message.type === 'answer' || message.type === 'ended') {
      const resolve = this.waiting.get(message.id)
      if (resolve) {
        this.waiting.delete(message.id)
        resolve(message.type === 'answer' ? { answer: message.answer } : { reason: message.reason })
      }
    }
  }

  send(message) {
    if (this.trusted && this.socket) this.socket.send(JSON.stringify(message))
  }

  ask(message) {
    if (!this.trusted) return Promise.resolve({ reason: 'unavailable' })
    return new Promise(resolve => {
      this.waiting.set(message.id, resolve)
      this.send({ type: 'ask', ...message })
    })
  }
}

// Decides what to ask and carries answers back to Hermes, one prompt at a time.
class Coordinator {
  constructor({ rpc, link, settings, newId, onChange }) {
    Object.assign(this, { rpc, link, settings, newId, onChange })
    this.queue = []
    this.seen = new Set()
    this.current = null
    this.running = false
    this.last = null
  }

  remember(key) {
    this.seen.add(key)
    if (this.seen.size > SEEN_LIMIT) this.seen.delete(this.seen.values().next().value)
  }

  offerApproval(sessionId, request) {
    // Without a request id an answer couldn't be tied to this prompt, so it stays on screen.
    if (!this.settings().enabled || !sessionId || !request || !request.request_id) return
    this.offer({ kind: 'approval', key: `a:${sessionId}:${request.request_id}`, sessionId, request })
  }

  offerQuestion(sessionId, promptId, params) {
    if (!this.settings().enabled || !this.settings().questions || !sessionId || !promptId) return
    this.offer({ kind: 'question', key: `q:${sessionId}:${promptId}`, sessionId, promptId, params })
  }

  offer(item) {
    if (this.seen.has(item.key)) return
    this.remember(item.key)
    this.queue.push(item)
    void this.drain()
  }

  // Called with each poll. If a prompt was answered on screen or timed out, stop asking about it.
  reconcile(sessionId, pending) {
    const live = new Set(pending.map(p => p.request_id))
    this.queue = this.queue.filter(item => !(item.kind === 'approval' && item.sessionId === sessionId && !live.has(item.request.request_id)))
    const now = this.current
    if (now && now.kind === 'approval' && now.sessionId === sessionId && !live.has(now.request.request_id) && now.askId) {
      this.link.send({ type: 'cancel', id: now.askId })
    }
  }

  async drain() {
    if (this.running) return
    this.running = true
    while (this.queue.length) {
      const item = this.queue.shift()
      this.current = item
      this.onChange()
      try {
        await (item.kind === 'approval' ? this.runApproval(item) : this.runQuestion(item))
      } catch (error) {
        this.note(item, 'error', String((error && error.message) || error))
      }
      this.current = null
      this.onChange()
    }
    this.running = false
  }

  note(item, outcome, detail) {
    this.last = { kind: item.kind, outcome, detail: detail || '' }
    this.onChange()
  }

  async ask(item, text, { confirm = false, mode = 'gesture' } = {}) {
    const { listenSeconds } = this.settings()
    const id = this.newId()
    item.askId = id
    // The helper fetches Gemini's voice itself, so the key never leaves the Mac's Keychain.
    const pending = this.link.ask({ id, mode, text, listenSeconds, confirm })
    const result = await pending
    item.askId = null
    return result
  }

  async stillWaiting(item) {
    const reply = await this.rpc('approval.pending', { session_id: item.sessionId }, 5000)
    const found = ((reply && reply.approvals) || []).find(p => p.request_id === item.request.request_id)
    return Boolean(found && found.command === item.request.command)
  }

  async runApproval(item) {
    const { request, sessionId } = item
    const result = await this.ask(item, approvalSpeech(request), { confirm: this.settings().confirmApprovals })
    if (!result.answer) {
      this.note(item, 'unanswered', result.reason)
      return
    }
    const offered = Array.isArray(request.choices) && request.choices.length ? request.choices : ['once', 'deny']
    const choice = result.answer === 'yes' ? 'once' : 'deny'
    if (!offered.includes(choice) || !(await this.stillWaiting(item))) {
      this.note(item, 'stale')
      return
    }
    await this.rpc('approval.respond', { session_id: sessionId, request_id: request.request_id, choice }, 30000)
    this.note(item, choice === 'once' ? 'approved' : 'denied')
  }

  async answerQuestion(item, plan, answer) {
    await this.rpc('clarify.respond', { session_id: item.sessionId, request_id: item.promptId, answer }, 30000)
    this.note(item, 'answered', answer)
  }

  async runQuestion(item) {
    const plan = questionPlan(item.params || {})
    if (plan.mode === 'read') {
      await this.ask(item, plan.text, { mode: 'say' })
      this.note(item, 'read')
      return
    }
    if (plan.mode === 'pair') {
      const result = await this.ask(item, pickerSpeech(plan.question, plan.choices))
      if (!result.answer) {
        this.note(item, 'unanswered', result.reason)
        return
      }
      await this.answerQuestion(item, plan, plan.choices[result.answer === 'yes' ? 0 : 1])
      return
    }
    for (let i = 0; i < plan.choices.length; i++) {
      const result = await this.ask(item, optionSpeech(plan.question, plan.choices[i], i, plan.choices.length))
      if (result.answer === 'yes') {
        await this.answerQuestion(item, plan, plan.choices[i])
        return
      }
      if (!result.answer) {
        this.note(item, 'unanswered', result.reason)
        return
      }
    }
    this.note(item, 'unanswered', 'no option chosen')
  }
}

const PLUGIN_ID = 'airpods-approvals'
const STYLE_ID = 'apa-plugin-style'
const CSS = ".apa-chip { display: inline-flex; align-items: center; gap: 5px; height: 100%; padding: 0 6px; border: 0; background: none; color: inherit; font: inherit; font-size: 11px; cursor: pointer; }\n.apa-chip:hover { background: var(--dt-hover, color-mix(in srgb, currentColor 8%, transparent)); }\n.apa-beats { display: inline-flex; align-items: center; gap: 3px; }\n.apa-beat { width: 5px; height: 5px; border-radius: 50%; background: currentColor; opacity: 0.22; transition: opacity 90ms ease-out, transform 90ms ease-out; }\n.apa-beat--on { opacity: 1; transform: scale(1.3); }\n.apa-beats--miss .apa-beat { animation: apa-miss 200ms ease-out; }\n.apa-beats--large { gap: 8px; }\n.apa-beats--large .apa-beat { width: 10px; height: 10px; }\n.apa-try { display: flex; align-items: center; gap: 12px; }\n.apa-key { display: flex; align-items: center; gap: 8px; }\n.apa-key input { width: 220px; }\n.apa-note { font-size: 12px; opacity: 0.7; }\n@keyframes apa-miss { 40% { transform: translateX(2px); } 80% { transform: translateX(-2px); } }\n@media (prefers-reduced-motion: reduce) {\n  .apa-beat { transition: none; }\n  .apa-beats--miss .apa-beat { animation: none; }\n}\n"
const POLL_MS = 2000
const MAX_POLLED_SESSIONS = 12

const $state = atom({ helper: 'off', output: null, motionDenied: false, beats: 0, listening: false, missed: 0, asking: null, last: null, geminiKey: false, test: '' })
const $settings = atom({ ...DEFAULT_SETTINGS })

let plugin = null
let link = null
let coordinator = null

function patch(values) {
  $state.set({ ...$state.get(), ...values })
}

function saveSettings(values) {
  const next = { ...$settings.get(), ...values }
  $settings.set(next)
  plugin.storage.set('settings', next)
}

function randomHex(bytes) {
  return hex(crypto.getRandomValues(new Uint8Array(bytes)))
}

async function sign(secret, text) {
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  return hex(new Uint8Array(await crypto.subtle.sign('HMAC', key, encoder.encode(text))))
}

function pairingToken() {
  return plugin.storage.get('token', '')
}

// Connect makes the token here, starts the helper by opening its app, and offers the token over the
// local socket. The helper takes it only if it has never been paired or Pair Again is open.
async function connectHelper() {
  let token = pairingToken()
  if (!token) {
    token = randomHex(32)
    plugin.storage.set('token', token)
  }
  patch({ helper: 'connecting' })
  link.pairSoon()
  link.connect()
  await plugin.os.openExternal(HELPER_APP)
  plugin.setTimeout(() => {
    if (!link.connected && $state.get().helper === 'connecting') patch({ helper: link.refused ? 'refused' : 'missing' })
  }, 12000)
}

function syncLink() {
  const status = link.status || {}
  const current = $state.get().helper
  patch({
    helper: link.connected ? 'ready' : link.refused ? 'refused' : current === 'connecting' ? 'connecting' : pairingToken() ? 'waiting' : 'off',
    output: status.output || null,
    motionDenied: Boolean(status.motionDenied),
    geminiKey: Boolean(status.geminiKey)
  })
}

function syncCoordinator() {
  const item = coordinator.current
  patch({
    asking: item ? item.kind : null,
    last: coordinator.last,
    ...(item ? {} : { beats: 0, listening: false })
  })
}

function hearProgress(message) {
  const state = $state.get()
  if (message.state === 'listening') patch({ listening: true, beats: 0 })
  else if (message.state === 'beat') patch({ beats: message.beats })
  else if (message.state === 'missed') patch({ beats: 0, missed: state.missed + 1 })
  else if (message.state === 'confirm') patch({ listening: false, beats: 0 })
}

// ── hearing Hermes ──────────────────────────────────────────────────────────────────────────────

function hearEvent(event) {
  if (!event || !event.session_id || !link.connected || !link.status.geminiKey) return
  const payload = event.payload || {}
  if (event.type === 'approval.request') {
    coordinator.offerApproval(event.session_id, { ...payload, request_id: payload.request_id || payload.prompt_id })
  } else if (event.type === 'clarify.request') {
    const questions = Array.isArray(payload.questions)
      ? payload.questions
      : [{ qid: payload.prompt_id, question: payload.question, choices: payload.choices, multi_select: payload.multi_select }]
    coordinator.offerQuestion(event.session_id, payload.prompt_id || payload.request_id, { questions })
  }
}

// Events are the fast path. This poll also catches prompts from sessions Desktop has not opened,
// and notices when a prompt was answered on screen.
let polling = false

async function poll() {
  if (polling || !$settings.get().enabled || !link.connected || !link.status.geminiKey) return
  polling = true
  try {
    const focused = host.state.focusedSessionId.get()
    const reply = await host.request('session.active_list', { current_session_id: focused || null }, 8000)
    const sessions = ((reply && reply.sessions) || []).slice(-MAX_POLLED_SESSIONS)
    await Promise.all(
      sessions.map(async session => {
        const answer = await host.request('approval.pending', { session_id: session.id }, 5000).catch(() => null)
        if (!answer) return
        const pending = answer.approvals || []
        coordinator.reconcile(session.id, pending)
        pending.forEach(request => coordinator.offerApproval(session.id, request))
      })
    )
  } catch {
    // The connection may be down; the next poll tries again.
  } finally {
    polling = false
  }
}

// A practice run: it uses the real helper and gestures, and never touches Hermes.
async function tryGesture() {
  patch({ test: 'Listening', beats: 0 })
  const { listenSeconds, confirmApprovals } = $settings.get()
  const result = await link.ask({
    id: `try-${randomHex(4)}`,
    mode: 'gesture',
    text: 'Nod to say yes, or shake to say no.',
    listenSeconds,
    confirm: confirmApprovals
  })
  const words = { yes: 'You nodded', no: 'You shook your head' }
  const reasons = { ...REASONS, timeout: 'No gesture heard' }
  patch({ test: words[result.answer] || reasons[result.reason] || 'Stopped', beats: 0, listening: false })
}

// ── interface ───────────────────────────────────────────────────────────────────────────────────

function Beats({ large }) {
  const { beats, missed } = useValue($state)
  return jsx('span', {
    className: `apa-beats${large ? ' apa-beats--large' : ''}${missed % 2 ? ' apa-beats--miss' : ''}`,
    'aria-label': `${beats} of 3 beats`,
    children: [1, 2, 3].map(n => jsx('span', { className: n <= beats ? 'apa-beat apa-beat--on' : 'apa-beat' }, n))
  })
}

function StatusChip() {
  const state = useValue($state)
  const settings = useValue($settings)
  if (!settings.enabled) return null
  const title = state.helper === 'ready' ? (state.output ? `AirPods Approvals: ${state.output}` : 'AirPods Approvals: connect your AirPods') : 'AirPods Approvals: helper not connected'
  return jsx('button', {
    className: 'apa-chip',
    onClick: () => host.navigate(pluginSettingsHref(PLUGIN_ID)),
    title,
    type: 'button',
    children: state.listening
      ? jsx(Beats, {})
      : [jsx(Codicon, { name: state.helper === 'ready' && state.output ? 'unmute' : 'mute', size: '0.8rem' }, 'i')]
  })
}

function helperText(state) {
  if (state.helper === 'missing') return 'Helper not found'
  if (state.helper === 'refused') return 'Choose Pair Again in the menu bar, then Connect'
  if (state.helper === 'connecting') return 'Connecting'
  if (state.helper === 'waiting') return 'Helper not running'
  if (state.helper === 'off') return 'Not connected'
  if (state.motionDenied) return 'Motion access is off'
  return state.output ? `Ready on ${state.output}` : 'Connect your AirPods'
}

const REASONS = {
  unavailable: 'AirPods not ready',
  noMotion: 'No head movement. Are both AirPods in?',
  noKey: 'Add a Gemini key',
  noVoice: "Gemini didn't answer",
  lost: 'AirPods lost'
}

function outcomeText(last) {
  if (!last) return 'Nothing asked yet'
  const text = { approved: 'Approved', denied: 'Denied', answered: `Answered: ${last.detail}`, read: 'Read aloud', stale: 'Already answered on screen', error: 'Could not send that answer' }
  if (last.outcome === 'unanswered') return `${REASONS[last.detail] || 'No answer given'}, left on screen`
  return text[last.outcome] || last.outcome
}

// The key goes straight to the helper, which keeps it in the Keychain. Desktop never stores it.
function KeyRow({ state }) {
  const [draft, setDraft] = useState('')
  const linked = state.helper === 'ready'
  if (state.geminiKey) {
    return jsx(ListRow, {
      title: 'Gemini key',
      description: 'Saved',
      action: jsx(Button, { onClick: () => link.send({ type: 'setKey', key: '' }), size: 'sm', type: 'button', variant: 'outline', children: 'Remove' })
    })
  }
  const save = () => {
    if (!draft.trim()) return
    link.send({ type: 'setKey', key: draft.trim() })
    setDraft('')
  }
  return jsx(ListRow, {
    title: 'Gemini key',
    action: jsxs('span', {
      className: 'apa-key',
      children: [
        jsx(Input, {
          'aria-label': 'Gemini API key',
          autoComplete: 'off',
          disabled: !linked,
          onChange: event => setDraft(event.target.value),
          onKeyDown: event => event.key === 'Enter' && save(),
          placeholder: 'Paste key',
          spellCheck: false,
          type: 'password',
          value: draft
        }),
        jsx(Button, { disabled: !linked || !draft.trim(), onClick: save, size: 'sm', type: 'button', variant: 'default', children: 'Save' })
      ]
    })
  })
}

function SettingsPage() {
  const state = useValue($state)
  const settings = useValue($settings)
  const ready = state.helper === 'ready' && Boolean(state.output) && !state.motionDenied && state.geminiKey
  return jsxs('div', {
    children: [
      jsx(ListRow, {
        title: 'Helper',
        description: helperText(state),
        action: state.helper === 'ready' ? null : jsx(Button, { onClick: () => void connectHelper(), size: 'sm', type: 'button', variant: 'default', children: 'Connect' })
      }),
      jsx(KeyRow, { state }),
      jsx(ListRow, {
        title: 'Try it',
        description: state.test || 'Three quick beats',
        action: jsxs('span', {
          className: 'apa-try',
          children: [jsx(Beats, { large: true }), jsx(Button, { disabled: !ready || Boolean(state.asking), onClick: () => void tryGesture(), size: 'sm', type: 'button', variant: 'outline', children: 'Start' })]
        })
      }),
      jsx(ListRow, { title: 'Last request', description: outcomeText(state.last) }),
      jsx(ToggleRow, { checked: settings.enabled, label: 'Answer with my head', onChange: on => saveSettings({ enabled: on }) }),
      jsx(ToggleRow, { checked: settings.confirmApprovals, label: 'Nod twice to approve', description: 'A second round before anything runs.', onChange: on => saveSettings({ confirmApprovals: on }) }),
      jsx(ToggleRow, { checked: settings.questions, label: 'Read questions aloud', onChange: on => saveSettings({ questions: on }) }),
      jsx(ListRow, {
        title: 'Time to answer',
        action: jsx(SegmentedControl, {
          onChange: value => saveSettings({ listenSeconds: Number(value) }),
          options: [{ id: '5', label: '5s' }, { id: '8', label: '8s' }, { id: '12', label: '12s' }],
          value: String(settings.listenSeconds)
        })
      })
    ]
  })
}

// ── registration ────────────────────────────────────────────────────────────────────────────────

export default {
  id: PLUGIN_ID,
  name: 'AirPods Approvals',
  description: 'Hear approvals in your AirPods and answer with a nod or a shake.',
  register(ctx) {
    plugin = ctx
    if (!document.getElementById(STYLE_ID)) {
      const style = document.createElement('style')
      style.id = STYLE_ID
      style.textContent = CSS
      document.head.appendChild(style)
      ctx.onDispose(() => style.remove())
    }

    $settings.set({ ...DEFAULT_SETTINGS, ...ctx.storage.get('settings', {}) })

    link = new HelperLink({
      createSocket: url => new WebSocket(url),
      token: pairingToken,
      sign,
      nonce: () => randomHex(16),
      onChange: syncLink,
      setTimer: (fn, ms) => ctx.setTimeout(fn, ms)
    })
    link.progress = hearProgress

    coordinator = new Coordinator({
      rpc: (method, params, timeout) => host.request(method, params, timeout),
      link,
      settings: () => $settings.get(),
      newId: () => randomHex(8),
      onChange: syncCoordinator
    })

    ctx.onEvent('*', hearEvent)
    ctx.setInterval(() => void poll(), POLL_MS)
    ctx.onDispose(() => link.close())

    ctx.registerMany([
      { id: 'status', area: STATUSBAR_AREAS.right, order: 112, render: () => jsx(StatusChip, {}) },
      { id: 'cmd-try', area: PALETTE_AREA, data: { id: 'airpods-approvals.settings', label: 'AirPods Approvals: Open settings', keywords: ['airpods', 'nod', 'approve'], run: () => host.navigate(pluginSettingsHref(PLUGIN_ID)) } }
    ])
    ctx.registerSettingsPage?.({ id: 'settings', title: 'AirPods Approvals', icon: 'unmute', render: () => jsx(SettingsPage, {}) })

    // Once paired, Desktop starts the helper itself. Only the first launch needs Connect.
    if (pairingToken()) {
      link.connect()
      ctx.setTimeout(() => {
        if (!link.connected) void ctx.os.openExternal(HELPER_APP)
      }, 1500)
    }
  }
}
